// Paint the Mac window card: the rounded card clipped (overflow
// hidden), the white body filling it, the purple title bar across the
// top, then the three filled traffic-light dots — green, yellow, red,
// left to right in the LTR header (his dotColors order). The text
// itself is painted per line by STYLE_PAINT.macwindow.
function paintMacWindowCard(l, fs) {
  const headerC = sp('macWindowHeaderC') || '#683bb7';
  const bodyC = sp('macWindowBodyC') || '#ffffff';
  const dotC1 = sp('macWindowDot1C') || '#4cb050';
  const dotC2 = sp('macWindowDot2C') || '#ffea3a';
  const dotC3 = sp('macWindowDot3C') || '#f54336';
  ctx.save();
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.clip();
  ctx.fillStyle = bodyC;
  ctx.fillRect(l.x, l.y, l.w, l.h);
  ctx.fillStyle = headerC;
  ctx.fillRect(l.x, l.y, l.w, l.headerH);
  const dotSize = 40; // his max dot size
  const gap = 14;     // his max gap between dots
  const padRight = 22; // his max header padding
  const dotY = l.y + (l.headerH - dotSize) / 2;
  const dot3x = l.x + l.w - padRight - dotSize; // red (last, rightmost)
  const dot2x = dot3x - gap - dotSize;          // yellow
  const dot1x = dot2x - gap - dotSize;          // green
  ctx.fillStyle = dotC1;
  ctx.beginPath();
  ctx.arc(dot1x + 20, dotY + 20, 20, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = dotC2;
  ctx.beginPath();
  ctx.arc(dot2x + 20, dotY + 20, 20, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = dotC3;
  ctx.beginPath();
  ctx.arc(dot3x + 20, dotY + 20, 20, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

// --- Heart footer card (Reza, 2026-11-23 — his createHeartFooterCard
// code): a pink card with the text in the upper part, a thin dark
// teal divider line across the full width, and a footer bar with a
// filled heart icon centred in it.

// His heart SVG path, verbatim (24x24 viewBox).
const HEART_PATH = 'M12 21.2 C10.5 18.9 4.2 14.2 4.2 8.8 C4.2 5.7 6.5 3.5 9.1 3.5 C10.6 3.5 11.6 4.5 12 5.8 C12.4 4.5 13.4 3.5 14.9 3.5 C17.5 3.5 19.8 5.7 19.8 8.8 C19.8 14.2 13.5 18.9 12 21.2 Z';

// Geometry of the heart footer card around the text block. Same shape
// as the window card layout (fixed px padding, height floor splitting
// evenly, blockShift following the alignment buttons), but the chrome
// hangs BELOW the text instead of above it: the text is centred in
// the body (the upper part), then the divider and the footer follow.
function heartLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  const padX = 40;                    // his max body padding left/right
  const bodyPadTop = 44, bodyPadBottom = 44; // his max body padding
  const dividerH = 4;                 // his max divider height
  const footerH = 48;                 // his max footer height
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padX * 2, sp('heartCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padX * 2 - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack
    : state.align === 'left' ? -slack
    : state.align === 'justify' ? (rtl ? slack : -slack)
    : 0;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - bodyPadTop;
  let cardBottom = textBottom + bodyPadBottom + dividerH + footerH;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred in the
  // body.
  const extraH = Math.max(0, sp('heartCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 20,
    padX, dividerH, footerH, blockShift, rtl,
  };
}

// Paint the heart footer card: the rounded pink card clipped
// (overflow hidden), the thin accent divider across the full width
// above the footer, and his heart path filled with the accent colour,
// centred in the footer. The text itself is painted per line by
// STYLE_PAINT.heart.
function paintHeartCard(l, fs) {
  const cardC = sp('heartCardC') || '#eabcc5';
  const accentC = sp('heartAccentC') || '#415a6c';
  ctx.save();
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.clip();
  ctx.fillStyle = cardC;
  ctx.fillRect(l.x, l.y, l.w, l.h);
  const dividerY = l.y + l.h - l.footerH - l.dividerH;
  ctx.fillStyle = accentC;
  ctx.fillRect(l.x, dividerY, l.w, l.dividerH);
  const heartSize = 25; // his max heart size
  const footerY = l.y + l.h - l.footerH;
  const heartX = l.x + (l.w - heartSize) / 2;
  const heartY = footerY + (l.footerH - heartSize) / 2;
  ctx.save();
  ctx.translate(heartX, heartY);
  ctx.scale(heartSize / 24, heartSize / 24);
  ctx.fillStyle = accentC;
  ctx.fill(new Path2D(HEART_PATH));
  ctx.restore();
  ctx.restore();
}

// --- Glass notification card (Reza, 2026-11-23 — his
// createGlassNotificationCard code): a translucent glass panel with
// a small time label in the top-right corner and the text centred in
// it.

// Geometry of the glass notification card around the text block. Same
// shape as the other card layouts (fixed px padding, height floor
// splitting evenly, blockShift following the alignment buttons). The
// text is centred in the panel; the time label sits in the top-right
// corner.
function glassNotifLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  const padX = 46;                    // his max card padding left/right
  const padTop = 94, padBottom = 72;  // his max card padding top/bottom
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padX * 2, sp('glassNotifCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padX * 2 - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack
    : state.align === 'left' ? -slack
    : state.align === 'justify' ? (rtl ? slack : -slack)
    : 0;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - padTop;
  let cardBottom = textBottom + padBottom;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred in the
  // panel.
  const extraH = Math.max(0, sp('glassNotifCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 30,
    padX, blockShift, rtl,
  };
}

// Paint the glass notification card: the translucent panel (his rgba
// tint at 0.34) and the small time label in the top-right corner
// (his Inter 600, 25px, 0.01em tracking, white at 0.45 — drawn in
// Vazir, like the other chrome latin text in the app, since Inter is
// not loaded). NOTE: his backdrop-filter blur(12px) cannot be drawn
// on canvas — the tint reads as glass over the page's smooth gradient
// backgrounds, the same as the music and bell cards. The text itself
// is painted per line by STYLE_PAINT.glassnotif.
function paintGlassNotifCard(l, fs) {
  const cardC = sp('glassNotifCardC') || '#ffffff';
  const cardO = sp('glassNotifCardO') ?? 34;
  ctx.fillStyle = hexToRgba(cardC, cardO / 100);
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.fill();
  const timeText = sp('glassNotifTime') || 'now';
  const timeC = sp('glassNotifTimeC') || '#ffffff';
  const timeO = sp('glassNotifTimeO') ?? 45;
  // The time label draws at 25px with its own tracking and alignment
  // — wrapped in save/restore so none of it leaks into the main text
  // (without this, the label's 25px font stuck and the size slider
  // stopped resizing the text — Reza, 2026-11-23).
  ctx.save();
  ctx.fillStyle = hexToRgba(timeC, timeO / 100);
  ctx.font = `600 ${25}px 'Vazir'`;
  if ('letterSpacing' in ctx) ctx.letterSpacing = '0.25px';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'top';
  ctx.fillText(timeText, l.x + l.w - 42, l.y + 36);
  ctx.restore();
}

// Message bubble geometry: the bubble is a WIDE bar, NOT a hug —
// Reza's code sets min-width: min(88vw, 620px) with the text centred
// in it. The 88% alone (950px) took the whole page length on his
// phone (Reza, 2026-11-22 22:00: «کل طول صفحه رو می گیره») — so the
// width is max(text + side pads, min(88% of the 1080 canvas, 620)),
// i.e. the 620px cap from his code binds at the 1080 canvas width
// and the bubble spans 57% of the page, not the whole of it. The
// bubble itself NEVER moves (Reza 2026-11-22 22:09: the align buttons
// must move only the text INSIDE the bubble, not the whole bubble) —
// the text alignment happens in draw() via the bubble's inner width
// (see alignW there). The tail is Reza's exact SVG path
// (see paintMsgbubble): a 34x36 shape overlapping the bottom-right
// corner, its tip poking ~0.17x right of the bubble.
function msgbubbleLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  const padX = fs * 0.5;
  const padY = fs * 0.4;
  const w = Math.max(maxLw + padX * 2, Math.min(1080 * 0.88, 620));
  const hh = blockH + padY * 2;
  const r = Math.min(fs * (sp('msgbubbleR') / 100), hh / 2, w / 2);
  // The bubble stays centred on the canvas whatever the alignment is;
  // only the text inside it moves (draw() anchors the lines within
  // the bubble's inner width).
  const blockShift = 0;
  return {
    x: cx - w / 2 + blockShift, y: h / 2 - hh / 2, w, h: hh, r,
    padX, padY, blockShift,
    tailOut: fs * 0.17, tailDrop: fs * 0.01, rtl,
  };
}

// Paint the bubble: a rounded rect (the body) + the tail as a
// SEPARATE shape overlapping the bottom-right corner — Reza's exact
// code (2026-11-22 21:30, «این کد دقیقشه»), translated from his DOM
// version (a div + an SVG tail) into canvas paths. The app paints
// everything on canvas, so a DOM element cannot be used directly;
// the tail below is his SVG path verbatim, scaled so 1 SVG unit =
// 0.01x of fs: viewBox 0 0 34 36, the path
// M 17 0 C 17 18, 21 29, 34 35 C 23 36.5, 14 33, 8 28.5 L 8 12 L 17 0 Z,
// placed with its left edge 0.17x left of the bubble's right edge and
// its bottom on the bubble's bottom edge — exactly like his
// right:-17px / bottom:0 positioning. The tip pokes 0.17x out to the
// right. The bubble's bottom-right corner radius is 0.7x of the
// others, like his 22px vs 32px.
function paintMsgbubble(l, fs) {
  const bx = l.x, by = l.y, bw = l.w, bh = l.h, r = l.r;
  const rBR = r * 0.7;
  // The body.
  ctx.beginPath();
  ctx.moveTo(bx + r, by);
  ctx.lineTo(bx + bw - r, by);
  ctx.arcTo(bx + bw, by, bx + bw, by + r, r);
  ctx.lineTo(bx + bw, by + bh - rBR);
  ctx.arcTo(bx + bw, by + bh, bx + bw - rBR, by + bh, rBR);
  ctx.lineTo(bx + r, by + bh);
  ctx.arcTo(bx, by + bh, bx, by + bh - r, r);
  ctx.lineTo(bx, by + r);
  ctx.arcTo(bx, by, bx + r, by, r);
  ctx.closePath();
  ctx.fillStyle = sp('msgbubbleC');
  ctx.fill();
  // The tail — Reza's SVG path verbatim (see the header comment).
  const u = fs * 0.01;
  const ox = bx + bw - 17 * u, oy = by + bh - 36 * u;
  ctx.beginPath();
  ctx.moveTo(ox + 17 * u, oy);
  ctx.bezierCurveTo(ox + 17 * u, oy + 18 * u, ox + 21 * u, oy + 29 * u, ox + 34 * u, oy + 35 * u);
  ctx.bezierCurveTo(ox + 23 * u, oy + 36.5 * u, ox + 14 * u, oy + 33 * u, ox + 8 * u, oy + 28.5 * u);
  ctx.lineTo(ox + 8 * u, oy + 12 * u);
  ctx.lineTo(ox + 17 * u, oy);
  ctx.closePath();
  ctx.fillStyle = sp('msgbubbleC');
  ctx.fill();
}

// Droplet bubble geometry (Reza 2026-11-22 22:54 — a NEW bubble type
// from his second createChatBubble code): a uniformly round bubble
// (radius clamp(36px, 7vw, 54px) in his code — no special bottom-right
// corner) with a droplet tail that HANGS BELOW the bottom edge,
// inset from the right (bottom: -20px, right: 14px in his code).
// Width is max(text + side pads, min(86% of the 1080 canvas, 560)),
// i.e. his min(86vw, 560px) — the 560px cap binds at the 1080 canvas
// width and the bubble spans 52% of the page. The bubble itself NEVER
// moves (same rule as msgbubble, Reza 2026-11-22 22:09) — the text
// aligns inside it via the bubble's inner width (see alignW in draw()).
// The tail is his exact SVG path (see paintDropbubble): a 56x36 shape
// whose top edge sits 16u above the bubble's bottom and whose tip
// hangs 18u below it, 25u left of the bubble's right edge.
