            const visLw = lw + gaps[li] * Math.max(0, line.split(' ').filter((w) => w !== '').length - 1);
            lineJustifyGap = gaps[li];
            STYLE_PAINT.spiral(line, lcx, y, visLw, textFs);
            y += lineHeight;
